contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient, uint amount) public payable {
        require(address(this).balance >= amount);
        uint balBefore = address(this).balance;
        uint recBefore = (recipient == address(this)) ? 0 : recipient.balance;
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok);
        bool reverted;
        try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }
        uint got;
        if (recipient == address(this)) {
            got = address(this).balance - balBefore;
        } else {
            got = recipient.balance - recBefore;
        }
        assert(!reverted || got == amount);
    }
    receive() external payable {}
}

